<script setup lang="ts">
import { computed,ref } from 'vue';
import { compareReleaseNewest,releaseMetadata } from '../domain/catalog-release';
import GameIcon from './GameIcon.vue';
import LibraryToolbar from './LibraryToolbar.vue';
import CharacterLibraryTools from './CharacterLibraryTools.vue';
import SortPanel from './SortPanel.vue';
import ChoiceGroup from './ChoiceGroup.vue';
import FilterActions from './FilterActions.vue';
import WorkbenchDialog from './WorkbenchDialog.vue';
const props=defineProps<{options:{id:string;name:string;element?:string;rarity?:number;weaponType?:string}[];kind:'characters'|'weapons'|'artifacts';label:string;selectedId?:string;imageSize?:number;itemLabelPrefix?:string}>();
const emit=defineEmits<{select:[id:string]}>();
const query=ref(''),sort=ref('release'),direction=ref<'asc'|'desc'>('desc'),element=ref('all'),rarity=ref('all'),sortOpen=ref(false),filterOpen=ref(false);
const characterElements=ref<string[]>([]),characterWeapons=ref<string[]>([]),characterRarities=ref<string[]>([]);
const elements=[{value:'all',label:'全部'},...Object.entries({anemo:'风',geo:'岩',electro:'雷',dendro:'草',hydro:'水',pyro:'火',cryo:'冰'}).map(([value,label])=>({value,label}))];
const rarities=computed(()=>[...new Set(props.options.map(entry=>entry.rarity ?? releaseMetadata(props.kind,entry.id,entry.name)?.rarity).filter((value):value is number=>value!==undefined))].sort((a,b)=>b-a).map(value=>({value:String(value),label:`${value}星`})));
const entries=computed(()=>props.options.filter(entry=>entry.name.includes(query.value.trim()) && (props.kind==='characters'?(!characterElements.value.length || characterElements.value.includes(entry.element ?? '')) && (!characterWeapons.value.length || characterWeapons.value.includes(entry.weaponType ?? '')) && (!characterRarities.value.length || characterRarities.value.includes(String(entry.rarity ?? releaseMetadata(props.kind,entry.id,entry.name)?.rarity))):(element.value==='all' || entry.element===element.value)) && (rarity.value==='all' || String(entry.rarity ?? releaseMetadata(props.kind,entry.id,entry.name)?.rarity)===rarity.value)).sort((a,b)=>(direction.value==='desc'?1:-1)*(sort.value==='release'?compareReleaseNewest(releaseMetadata(props.kind,a.id,a.name),releaseMetadata(props.kind,b.id,b.name)):b.name.localeCompare(a.name,'zh-CN')) || a.name.localeCompare(b.name,'zh-CN')));
</script>
<template><section class="catalog-browser" :class="{'character-catalog':kind==='characters'}"><CharacterLibraryTools v-if="kind==='characters'" v-model:query="query" v-model:elements="characterElements" v-model:weapons="characterWeapons" v-model:rarities="characterRarities" v-model:sort="sort" v-model:direction="direction" :label="`搜索${label}`" :sort-options="[{value:'release',label:'实装版本'},{value:'name',label:'名称'}]" /><LibraryToolbar v-else v-model="query" :label="`搜索${label}`" placeholder="查找名称…" :filter-count="(element==='all'?0:1)+(rarity==='all'?0:1)" :sorted="sort!=='release' || direction!=='desc'" @sort="sortOpen=true" @filter="filterOpen=true" @reset="element='all';rarity='all';sort='release';direction='desc'" /><div class="catalog-browser-options"><button v-for="entry in entries" :key="entry.id" class="catalog-browser-item" :class="{selected:entry.id===selectedId}" :aria-label="`${itemLabelPrefix ?? '选择'}${entry.name}`" @click="emit('select',entry.id)"><GameIcon :kind="kind" :id="entry.id" :name="entry.name" :size="imageSize ?? 64" /><strong>{{ entry.name }}</strong></button></div><p v-if="!entries.length">没有符合条件的内容。</p><WorkbenchDialog v-if="sortOpen" center-title title="目录排序" size="filter" @close="sortOpen=false"><SortPanel v-model="sort" v-model:direction="direction" :options="[{value:'release',label:'实装版本'},{value:'name',label:'名称'}]" @reset="sort='release';direction='desc'" @confirm="sortOpen=false" /></WorkbenchDialog><WorkbenchDialog v-if="filterOpen" center-title title="筛选目录" size="filter" @close="filterOpen=false"><ChoiceGroup v-if="kind==='characters'" v-model="element" :options="elements" label="元素" /><ChoiceGroup v-if="rarities.length" v-model="rarity" :options="[{value:'all',label:'全部星级'},...rarities]" label="星级" /><template #footer><FilterActions flush @reset="element='all';rarity='all'" @confirm="filterOpen=false" /></template></WorkbenchDialog></section></template>
<style scoped>.catalog-browser { display:grid; gap:16px; min-width:0; }.character-catalog { display:block; }.character-catalog .catalog-browser-options { margin-top:16px; }.catalog-browser-options { display:grid; grid-template-columns:repeat(auto-fill,minmax(116px,1fr)); gap:12px; }.catalog-browser-item { display:flex; flex-direction:column; align-items:center; justify-content:center; gap:10px; padding:12px; border:1px solid var(--line); border-top:3px solid var(--line); border-radius:10px; background:var(--surface); color:var(--ink); font-size:var(--font-control); }.catalog-browser-item:hover,.catalog-browser-item.selected { border-top-color:var(--element-anemo-primary); }.catalog-browser-item.selected { background:var(--element-anemo-light); }.catalog-browser p { font-size:var(--font-control); }</style>
